from wine_places p, snap, geom where p.canonical_key='italy.friuli';
do $$ declare n int; begin select count(*) into n from wine_place_boundaries b join wine_places p on p.id=b.wine_place_id where p.canonical_key='italy.friuli' and b.is_current; if n<>1 then raise exception 'expected 1 Friuli region boundary, got %',n; end if; end $$;
